    rmax = max(r for r, c in sixes)
    cmin = min(c for r, c in sixes)
    cmax = max(c for r, c in sixes)

    row_counts = [sum(1 for r, c in sixes if r == rr) for rr in range(rmin, rmax + 1)]
    col_counts = [sum(1 for r, c in sixes if c == cc) for cc in range(cmin, cmax + 1)]

    # A T-shaped marker calls for a left-right reflection.
    if max(row_counts) > max(col_counts):
        if row_counts[0] > row_counts[-1]:  # T pointing upward
            edge = min(c for r, c in fours)
            for r, c in fours:
                nc = 2 * edge - 1 - c
                if 0 <= nc < w:
                    out[r][nc] = 4
        else:  # T pointing downward
            edge = max(c for r, c in fours)
            for r, c in fours:
                nc = 2 * edge + 1 - c
                if 0 <= nc < w:
                    out[r][nc] = 4
    else:
        # Cross-shaped marker: reflect vertically. Its horizontal offset
        # selects which side of the 4-shape receives the reflected copy.
        four_center = (min(c for r, c in fours) + max(c for r, c in fours)) / 2
        six_center = (cmin + cmax) / 2
        if abs(four_center - six_center) < 1:
            edge = max(r for r, c in fours)
            for r, c in fours:
                nr = 2 * edge + 1 - r
                if 0 <= nr < h:
                    out[nr][c] = 4
        else:
            edge = min(r for r, c in fours)
            for r, c in fours:
                nr = 2 * edge - 1 - r
                if 0 <= nr < h:
                    out[nr][c] = 4

