def transform(grid):
    h, w = len(grid), len(grid[0])
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [[0] * w for _ in range(h)]

    for r, c in fours:
        out[r][c] = 4

    # Find the marker's longest horizontal row and the vertical stem attached
    # to it. The marker directs which side receives a reflected copy.
    rows = {}
    for r, c in sixes:
        rows.setdefault(r, []).append(c)
    bar_row = max(rows, key=lambda r: len(rows[r]))
    bar_left, bar_right = min(rows[bar_row]), max(rows[bar_row])
    bar_center_twice = bar_left + bar_right

    stem_cols = [c for c in range(bar_left, bar_right + 1)
                 if any(rr != bar_row and cc == c for rr, cc in sixes)]
    stem_col = stem_cols[0] if stem_cols else (bar_left + bar_right) // 2

    # T marker: reflect horizontally. A downward stem directs the copy right;
    # an upward stem directs it left.
    if len(rows[bar_row]) <= 3:
        stem_down = any(r > bar_row for r, c in sixes)
        edge = max(c for r, c in fours) if stem_down else min(c for r, c in fours)
        for r, c in fours:
            nc = 2 * edge + (1 if stem_down else -1) - c
            if 0 <= nc < w:
                out[r][nc] = 4
    else:
        # Cross-like marker: reflect vertically. Stem offset picks direction.
        downward = 2 * stem_col > bar_center_twice
        edge = max(r for r, c in fours) if downward else min(r for r, c in fours)
        for r, c in fours:
            nr = 2 * edge + (1 if downward else -1) - r
            if 0 <= nr < h:
                out[nr][c] = 4

    return out
